mapper.insert:
/* setUser */
INSERT INTO TM_USERXM (
            PROF_NUMB
          , BGIM_NUMB
          , USER_IDXX
          , USER_NICK
          , USER_PROV
          , USER_ROLE
          , USER_STAT
          , ONBD_YSNO
          , INTR_CNTN
          , JOIN_DATE
) VALUES (  #{profNumb,jdbcType=NUMERIC}
          , #{bgimNumb,jdbcType=NUMERIC}
          , #{userIdxx}
          , #{userNick}
          , #{userProv,jdbcType=VARCHAR}
          , #{userRole}
          , #{userStat}
          , #{onbdYsno}
          , #{intrCntn,jdbcType=VARCHAR}
          , CURRENT_TIMESTAMP
)

mapper.update:
UPDATE /* uptUserProfile */
       TM_USERXM
   SET USER_NICK = #{userNick}
     , INTR_CNTN = #{intrCntn,jdbcType=VARCHAR}

     , PROF_NUMB = #{profNumb}


     , BGIM_NUMB = #{bgimNumb}

 WHERE USER_NUMB = #{userNumb}



UPDATE /* uptUserOnboarding */
       TM_USERXM
   SET USER_NICK = #{userNick}
     , ONBD_YSNO = #{commYes}
 WHERE USER_NUMB = #{userNumb}
   AND ONBD_YSNO = #{commNo}

mapper.select:
SELECT /* getUserNickDuplicateCnt */
       COUNT(1)
  FROM TM_USERXM
 WHERE USER_NICK = #{userNick}

   AND USER_NUMB != #{userNumb}

mapper.update:
UPDATE /* uptUserStatus */
       TM_USERXM
   SET USER_STAT = #{userStat}
     , WTHD_DATE = #{wthdDate,jdbcType=TIMESTAMP}
     , DELT_DATE = #{deltDate,jdbcType=TIMESTAMP}
 WHERE USER_NUMB = #{userNumb}



UPDATE /* uptUserReplyDeleted */
       TB_REPLXX
   SET DELT_YSNO = #{commYes}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE USER_NUMB = #{userNumb}
   AND COALESCE(DELT_YSNO, #{commNo}) != #{commYes}

